import{_ as e,a as r,c as o,ac as a}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"深入浅出Spring Boot 2.x","description":"按杨开振版17章整理 Spring Boot 2.x 的容器、数据访问、Web 与服务开发。","frontmatter":{"title":"深入浅出Spring Boot 2.x","description":"按杨开振版17章整理 Spring Boot 2.x 的容器、数据访问、Web 与服务开发。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 编程语言与开发框架","summary":"按杨开振版17章整理 Spring Boot 2.x 的容器、数据访问、Web 与服务开发。","status":"active","related":[{"title":"C语言程序设计","link":"/life/personal/books/computing/c-programming","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Go语言高并发与微服务实战","link":"/life/personal/books/computing/go-concurrency-microservices","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Redis设计与实现","link":"/life/personal/books/computing/redis-design","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Rust程序设计（第2版）","link":"/life/personal/books/computing/programming-rust","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"Go语言高并发与微服务实战","link":"/life/personal/books/computing/go-concurrency-microservices"},"next":{"text":"Redis设计与实现","link":"/life/personal/books/computing/redis-design"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Go语言高并发与微服务实战","link":"/life/personal/books/computing/go-concurrency-microservices"},"next":{"text":"Redis设计与实现","link":"/life/personal/books/computing/redis-design"}},"headers":[],"relativePath":"life/personal/books/computing/spring-boot-2.md","filePath":"life/personal/books/computing/spring-boot-2.md"}'),i={name:"life/personal/books/computing/spring-boot-2.md"};function n(d,t,l,s,p,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="深入浅出spring-boot-2-x" tabindex="-1">深入浅出Spring Boot 2.x <a class="header-anchor" href="#深入浅出spring-boot-2-x" aria-label="Permalink to &quot;深入浅出Spring Boot 2.x&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 编程语言与开发框架</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书的阅读目标是理解 Spring Boot 怎样简化 Java 应用的组织与运行。适合具备 Java 基础，希望将依赖注入、Web 开发、持久化和测试连接成完整后端应用的读者。</p><p>阅读时重点追踪一次请求：配置怎样被加载，组件怎样被创建，控制器怎样调用业务与数据库，异常如何变成响应。这样更容易理解自动配置提供了哪些便利，又在哪里保留了需要明确设置的边界。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>本页对应杨开振著、人民邮电出版社 2018 年出版的《深入浅出Spring Boot 2.x》，ISBN <strong>9787115486387</strong>。下表依据该 ISBN 的公开书目目录整理全部 17 章，附录另列；尚未直接复核出版社完整目录。书中包含当时的 Spring Cloud 组件，不能替换为 3.x 或当前生态再声称是原书内容。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>作者为杨开振，书目对应2018年人民邮电出版社版本。新疆大学公开课程大纲将本书列作参考书，能交叉核对作者、出版社与年份；它不证明作者当前任职。本页未取得完整的一手作者履历，因此只评价本书将 Spring 容器、Web、数据访问和部署联系起来的内容，不额外添加未经核实的资历。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合有 Java、基本 Web 与数据库经验，希望从传统 Spring 进入 Boot 2.x 的开发者。完全没有 Java 基础时信息量较大；维护旧项目的人可按 IoC、事务与 MVC 的实际问题选读。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>阅读关注点</th></tr></thead><tbody><tr><td>第1章 Spring Boot 来临</td><td>回顾 Spring 的发展，理解约定与自动配置试图降低的开发成本。</td></tr><tr><td>第2章 聊聊开发环境搭建和基本开发</td><td>搭建工程，认识依赖、自动配置和自定义配置。</td></tr><tr><td>第3章 全注解下的 Spring IoC</td><td>介绍 Bean 装配、依赖注入、生命周期、作用域和条件配置。</td></tr><tr><td>第4章 开始约定编程——Spring AOP</td><td>通过代理与切面理解连接点、通知和织入，观察调用边界。</td></tr><tr><td>第5章 访问数据库</td><td>比较数据源、JdbcTemplate、JPA 与 MyBatis 的使用方式。</td></tr><tr><td>第6章 聊聊数据库事务处理</td><td>解释声明式事务、隔离级别和传播行为，并讨论自调用问题。</td></tr><tr><td>第7章 使用性能利器——Redis</td><td>使用 RedisTemplate、事务、流水线和缓存注解，关注缓存一致性。</td></tr><tr><td>第8章 文档数据库——MongoDB</td><td>配置 MongoDB，比较模板操作与仓库式数据访问。</td></tr><tr><td>第9章 初识 Spring MVC</td><td>沿请求处理流程理解控制器、视图和框架初始化。</td></tr><tr><td>第10章 深入 Spring MVC 开发</td><td>涵盖参数转换、校验、上传、拦截器、国际化与响应处理。</td></tr><tr><td>第11章 构建 REST 风格网站</td><td>用资源、HTTP 方法和状态码设计接口，并介绍 RestTemplate 调用。</td></tr><tr><td>第12章 安全——Spring Security</td><td>讨论用户认证、访问权限、HTTPS 与登录退出流程。</td></tr><tr><td>第13章 学点 Spring 其他的技术</td><td>汇集异步线程池、消息、定时任务与 WebSocket 的应用。</td></tr><tr><td>第14章 Spring 5 新框架——WebFlux</td><td>介绍响应式模型、服务端处理、WebClient 与函数式路由。</td></tr><tr><td>第15章 实践一下——抢购商品</td><td>以抢购业务讨论超发、悲观锁、乐观锁及 Redis 方案。</td></tr><tr><td>第16章 部署、测试和监控</td><td>将打包运行、测试、Actuator、HTTP 与 JMX 监控连接起来。</td></tr><tr><td>第17章 分布式开发——Spring Cloud</td><td>介绍书中使用的 Eureka、Ribbon、Feign、Hystrix 和 Zuul。</td></tr><tr><td>附录 Spring Boot 知识点补充</td><td>补充正文之外的相关知识，适合按需要回查。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>自动配置替你做了选择，理解仍要追到生效的条件。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>沿一个请求记录组件创建、控制器调用、事务边界、数据库操作与异常响应。再只改变一个条件，例如配置项或事务调用入口，预测哪些行为会改变；这能把“框架替我处理”转化为能追查的机制。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>主题覆盖广、案例连贯，但2018年的框架与 Spring Cloud 组件有明显时代边界，不能直接作为新项目技术选型清单。建议复现时固定依赖版本，迁移时分别核对配置、Java 基线及 API 变化，先保住行为再升级。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给想把 Spring 各部分串成完整请求流程的人：每读一章，多解释一个失败场景，就能减少对注解的机械记忆。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://book.douban.com/subject/30323325/" target="_blank" rel="noopener noreferrer">对应 ISBN 的中文书目与完整目录</a>：作者、2018 年版本与 17 章结构的核对来源。</li><li><a href="https://www.epubit.com/" target="_blank" rel="noopener noreferrer">异步社区</a>：出版社配套资源核对入口；本次未取得该书完整出版社目录。</li><li><a href="https://docs.spring.io/spring-boot/docs/2.7.18/reference/htmlsingle/" target="_blank" rel="noopener noreferrer">Spring Boot 2.7.18 参考文档</a>：2.x 文档参考；该小版本不代表本书案例版本。</li><li><a href="https://spring.io/guides" target="_blank" rel="noopener noreferrer">Spring 官方指南</a>：补充学习入口，阅读时需注意指南当前采用的版本。</li><li><a href="https://ss.xju.edu.cn/__local/2/AA/DE/250E8584214D55BBDA75E5E3F51_BF4717B9_425149.pdf" target="_blank" rel="noopener noreferrer">新疆大学公开课程大纲</a>：交叉核对作者、出版社和2018年出版信息，不作作者履历或逐章目录证据。</li></ul>',26)])])}const u=e(i,[["render",n]]);export{h as __pageData,u as default};
